const r = $input.first().json;
const correo = $('Disparador').first().json.datos.correo;
if (r.statusCode !== 200 || !r.body || !Array.isArray(r.body.users)) return [{ json: { ok: false, estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } }];
const u = r.body.users.find((x) => String(x.email || '').toLowerCase() === correo);
if (!u) return [{ json: { ok: false, estado: 404, cuerpo: { error: { codigo: 'NO_ENCONTRADO', mensaje: 'No hay ninguna cuenta con ese correo.' } } } }];
return [{ json: { ok: true, id: u.id, correo: u.email, nombre: (u.user_metadata || {}).nombre ?? null, verificado: !!u.email_confirmed_at } }];
